export const BY_RARITY: Record<Rarity, PoolEntry[]> = RARITY_ORDER.reduce((acc, rarity) => {
  acc[rarity] = POOL.filter((entry) => entry.rarity === rarity);
  return acc;
}, {} as Record<Rarity, PoolEntry[]>);

export function rarityRank(rarity: Rarity): number {
  return Math.max(0, RARITY_ORDER.indexOf(rarity));
}
